# November 21, 2026: a first scatter of places across North Dakota away from Bismarck and Mandan, which the only earlier
# research batch (nd_cumj) covered. Region claimed with tools/choose.py --thinnest (nd, 19 places before this batch).
# Sources read in this session: the State Historical Society of North Dakota's site pages (history.nd.gov/historicsites/...),
# the National Park Service's Maltese Cross Cabin and South Unit pages, McKenzie County Tourism's Grassy Butte page,
# the Fargo Theatre's own About page, HMdb.org marker texts, and the Wikipedia articles (tools/wiki_raw.py).
# Interiors were not visited by any source opened unless the entry says so.
from data_b import N
from data_ma import W
BATCH={'key':'nd_ssxv','label':'North Dakota: forts, homesteads and landmarks across the state','added':'2026-11-21 15:24'}

def SH(slug,label):
    return ['SHSND: '+label,'https://www.history.nd.gov/historicsites/%s/index.html'%slug]
def HM(m,label):
    return ['HMdb: '+label,'https://www.hmdb.org/m.asp?m=%s'%m]
FEE='Admission (SHSND page, read November 2026): adults $10, children 6 to 17 $5, under 6 and SHSND Foundation members free.'
FREE='Free admission, donations welcome (SHSND page).'
SHSWINTER='Tuesday after Labor Day to the Friday of Memorial Day weekend open only for events, school tours, rentals and by appointment (SHSND page).'

PLACES=[
N('fort-totten-state-historic-site','Fort Totten','Fort Totten','nd','fort','standing',47.9775,-98.99306,'site','open','walk','forts','1867–1959',
  'An army post built in 1867 on the south shore of Devils Lake; the brick buildings of 1868 replaced an earlier log fort. The army left in 1890, and from 1891 the post was a Bureau of Indian Affairs boarding school, a tuberculosis preventorium for Dakota children from 1935 to 1939, and then a reservation school, handed to the Spirit Lake tribe in 1959. The state took the old post that year and opened it as a historic site in 1960.',
  'Seventeen original buildings round the parade ground (the SHSND page; Wikipedia says a walking tour takes in 16), with museum exhibits, the Pioneer Daughters\' Museum, the Fort Totten Little Theatre and an inn in the old buildings. Wikipedia says the brick was locally made and had to be painted often to keep it from crumbling; the 2021 photograph in the article shows the brick painted white with red trim. Interiors are open as museum rooms in summer; their fittings were not checked.',
  'The best-kept frontier army post on the northern plains, later a boarding school for Native children.',
  'State Historical Society of North Dakota, 417 Cavalry Circle, on the southeast edge of the town of Fort Totten, on the Spirit Lake Reservation. '+FEE+' '+SHSWINTER+' The site also rents rooms in the Totten Trail Historic Inn. A mapped lot is on 1st Avenue about 140 m northeast of the parade ground.',
  [SH('totten','Fort Totten State Historic Site'),W('Fort Totten State Historic Site')],brick='no',
  th=[47.97826,-98.99153],thn='Lot on 1st Avenue',
  hours='Memorial Day weekend to Labor Day daily 9 a.m. to 5 p.m.; grounds open year-round Monday to Friday 9 a.m. to 4:30 p.m.'),
N('fort-buford-state-historic-site','Fort Buford','Williston','nd','fort','standing',47.98639,-104.00139,'site','open','walk','forts','1866–1895',
  'An army post begun in June 1866 near where the Yellowstone meets the Missouri, mostly built of adobe and cottonwood inside a wooden stockade, and later a large supply depot for the field campaigns. Sitting Bull surrendered here in 1881. It served 29 years.',
  'Three original things are left (SHSND): the stone powder magazine, built in 1875 of sandstone quarried north of the fort (Wikipedia), the post cemetery site, and a large officers\' quarters that now holds the museum. Wikipedia says the officers\' quarters standing today was built in 1871 to 1872 as the commanding officer\'s quarters. An adobe barracks was rebuilt on an original barracks site in 2004. The grounds have outdoor signs and a self-guided tour; interior fittings not checked.',
  'Where Sitting Bull handed over his rifle, at the meeting of two rivers.',
  'State Historical Society of North Dakota, 15349 39th Lane NW, about 22 miles southwest of Williston off Highways 1804 and 58. '+FEE+' The ticket also covers the Missouri-Yellowstone Confluence Interpretive Center. October to April the buildings open only for events, school tours, rentals and by appointment; the grounds and signs are open year-round. Picnic area and campground on site. A mapped lot is on 39th Lane NW beside the officers\' quarters.',
  [SH('buford','Fort Buford State Historic Site'),W('Fort Buford')],brick='?',
  th=[47.98581,-104.00108],thn='Lot on 39th Lane NW',
  hours='May 1 to September 30 daily 9 a.m. to 5 p.m.; grounds open year-round'),
N('fort-abercrombie-state-historic-site','Fort Abercrombie','Abercrombie','nd','fort','standing',46.44472,-96.71861,'site','open','walk','forts','1858–1877',
  'The first permanent army fort in what became North Dakota, on the Red River, authorised by Congress in 1857 and built in 1858; Wikipedia says it moved to higher ground in 1860 after floods. In the US-Dakota War of 1862 it was besieged by Dakota warriors for more than six weeks, held by Minnesota volunteers with settlers sheltering inside. It guarded the oxcart trails, wagon roads, stage routes and Red River steamboats until it was abandoned in 1877 and its buildings sold off.',
  'The original guardhouse, returned to the site by the WPA in 1939 to 1940, with three blockhouses and a stockade rebuilt then and refurbished since, and a new interpretive centre. Wikipedia says native grass is left to grow where missing buildings stood, to show their size and shape. Interior of the guardhouse not checked.',
  '',
  'State Historical Society of North Dakota, 935 Broadway North, Abercrombie, about 35 miles south of Fargo. '+FEE+' '+SHSWINTER+' The grounds are open year-round. Parking was not checked: the nearest lots OpenStreetMap maps are in the town about 1 km west, so look for the site\'s own lot by the interpretive centre.',
  [SH('abercrombie','Fort Abercrombie State Historic Site'),W('Fort Abercrombie')],brick='?',
  hours='Memorial Day weekend to Labor Day daily 9 a.m. to 5 p.m.; grounds open year-round'),
N('chateau-de-mores-medora','Chateau de Mores','Medora','nd','landmark','standing',46.91111,-103.5325,'area','open','walk','','1883',
  'A 26-room, two-storey frame house built in 1883 as the summer home and hunting lodge of the Marquis de Mores, the French nobleman who founded Medora, named it for his wife, and tried to slaughter cattle on the range and ship the meat east in refrigerated cars. After 1886 the family came back only a few times, the last in 1903.',
  'A house museum holding many of the de Mores family\'s own furnishings and belongings (SHSND), shown in summer; allow an hour. An interpretive centre stands nearby. The packing plant chimney in Chimney Park on the west edge of town and the 1926 statue in de Mores Memorial Park belong to the same site.',
  'A French marquis\'s hunting lodge in the Badlands, still with his family\'s furniture.',
  'State Historical Society of North Dakota, 3426 Chateau Road, about 1/8 mile west and 1/8 mile south of Medora. '+FEE+' Closed on the holidays the page lists (New Year, Martin Luther King Jr. Day, Presidents Day, Good Friday, Veterans Day, Thanksgiving and the day after, Christmas Eve and Day). Mapped lot on Chateau Road about 480 m north of the house; the site\'s own parking by the interpretive centre was not checked.',
  [SH('chateau','Chateau de Mores State Historic Site'),W('Chateau de Mores')],brick='no',
  th=[46.91535,-103.53407],thn='Lot on Chateau Road',
  hours='Chateau May 1 to September 30 daily 9 a.m. to 5 p.m., closed in winter; interpretive centre also October to April Tuesday to Saturday 9 to 5'),
N('fort-clark-trading-post-site','Fort Clark Trading Post and earthlodge village site','Fort Clark','nd','town','traces',47.25258,-101.27433,'site','public','walk','','1822',
  'A Mandan earthlodge village built on the Missouri bluffs in 1822, later an Arikara one, with two fur posts beside it: Fort Clark, built by James Kipp for the American Fur Company in 1830, and Primeau\'s Post. Smallpox and cholera epidemics killed most of the people who lived here. When the Arikara town and Primeau\'s Post ended was not in the sources read.',
  'Archaeological remains of the large village, its cemetery and both trading posts, protected on the ground (SHSND); nothing stands. The bare-ground LiDAR shows round lodge pits where the pin is; they were not seen on the ground.',
  'A fur post beside an earthlodge town that epidemics emptied.',
  'State Historical Society of North Dakota, 1 1/4 miles west of the town of Fort Clark in Mercer County, about 15 miles southwest of Washburn off ND 200 Alt. Open year-round with no snow removal (SHSND page). Parking was not checked: no lot is mapped, so park where the site road ends and stay on the paths.',
  [SH('clark','Fort Clark State Historic Site'),W('Fort Clark Trading Post State Historic Site')],brick='no',
  hours='Open year-round; no snow removal'),
N('gingras-trading-post-walhalla','Gingras Trading Post','Walhalla','nd','landmark','standing',48.93694,-97.89083,'site','public','walk','','1840s',
  'The home and trading post of Antoine Blanc Gingras, a Metis fur trader and legislator, built in the 1840s northeast of Walhalla. Gingras claimed a fortune of $60,000 in 1861 and went on to run a chain of posts across northern Dakota Territory and southern Manitoba. His hand-hewn oak buildings are among the few remains of the fur trade in the Red River Valley.',
  'Two restored buildings: the two-storey trading post with its logs bare, and the house, its log frame covered in clapboard soon after it was built, painted deep red with white trim from traces of the original paint. Inside, the house is painted in its first colours: blue walls, yellow floors, pink ceilings and green and brown trim, with panels on Gingras and the fur trade; reproduction trade goods are sold in the store (SHSND). The page gives no hours for the buildings.',
  '',
  'State Historical Society of North Dakota, 12899 105th Street NE, 1 1/2 miles northeast of Walhalla. The grounds and outdoor signs are open year-round; when the buildings open is not on the page read (hours not checked: ask SHSND before going for the interiors). Parking was not checked: no lot is mapped.',
  [SH('gingras','Gingras Trading Post State Historic Site'),W('Gingras Trading Post State Historic Site')],brick='no',
  hours='Grounds open year-round'),
N('stutsman-county-courthouse-jamestown','Stutsman County Courthouse','Jamestown','nd','civic','standing',46.90409,-98.70536,'site','open','walk','','1883',
  'North Dakota\'s oldest surviving courthouse, built in 1883 to the design of Henry C. Koch of Wisconsin, and one of only two Gothic Revival courthouses in the state. Delegates to the state constitutional convention were elected here and statehood meetings held in 1885. Wikipedia says the west wing was added in 1926. The county left in the early 1980s and tried to pull it down for a parking lot; after fifteen years in court it went to the State Historical Society in 1987.',
  'Pressed metal lines the inside walls: SHSND calls it the most complete pressed tin interior in North Dakota and perhaps the Midwest. Restoration of the interior is going on, and visitors see the work in progress. The 2012 photograph in the Wikipedia article shows red brick walls on a stone base, with a tall brick clock tower. The escape room in the building is closed during construction.',
  'The birthplace of statehood, saved from becoming a parking lot, and lined inside with pressed tin.',
  'State Historical Society of North Dakota, 504 Third Avenue SE, Jamestown. Free admission, donations welcome. Closed on the state holidays the page lists. Street parking.',
  [SH('stutsmancc','Stutsman County Courthouse'),W('Stutsman County Courthouse and Sheriff\'s Residence/Jail')],brick='yes',
  hours='Memorial Day weekend to Labor Day daily 9 a.m. to 5 p.m.; rest of the year Tuesday to Saturday 9 a.m. to 5 p.m.'),
N('welk-homestead-strasburg','Welk Homestead','Strasburg','nd','landmark','standing',46.15033,-100.20745,'site','open','walk','','1899–1965',
  'The farm of Ludwig and Christina Welk, Germans from Russia who came from near Odessa in 1893. Their sixth child, the bandleader Lawrence Welk, was born here in 1903 and left in 1924. Their youngest son, Michael, farmed it until 1965. Sources differ on the house: SHSND says it was built in 1899, Wikipedia 1893.',
  'The house is built of batsa, dried mud brick, the way Germans from Russia built on the steppe and on the prairie. A summer kitchen, outhouse, blacksmith shop, granary and a barn moved here about 1949 are open in season, self-guided (SHSND). Interior fittings not checked.',
  'A mud-brick farmhouse of the Germans from Russia, where Lawrence Welk learned the accordion.',
  'State Historical Society of North Dakota, 845 88th Street SE, northwest of Strasburg: north 1/2 mile on US 83 to 88th Street, about 2 miles to 8th Avenue SE, and the farm drive is on the east side of the road (SHSND). '+FEE+' Outside the summer season it opens only for events, school tours, rentals and by appointment.',
  [SH('welk','Welk Homestead State Historic Site'),W('Ludwig and Christina Welk Homestead')],brick='no',conf='mixed',
  hours='Memorial Day weekend to Labor Day Thursday to Sunday 10 a.m. to 5 p.m.'),
N('oscar-zero-missile-alert-facility','Oscar-Zero Missile Alert Facility (Ronald Reagan Minuteman Missile Site)','Cooperstown','nd','fort','standing',47.49765,-98.12715,'site','open','drive','','',
  'One of the two last pieces of the 321st Missile Wing, whose Minuteman launch sites were spread over 6,500 square miles round Grand Forks Air Force Base. SHSND calls Oscar-Zero the last intact launch control centre of the wing. With the November-33 launch facility, two miles east of Cooperstown, it opened as a state historic site on July 13, 2009.',
  'Guided tours of the topside buildings, where the facility managers, guards and cooks lived, and, for those who choose, down the elevator shaft to the underground equipment building and launch control centre behind the concrete blast door. At November-33 the topside is as it was: the launch closure door, the security fence and the ventilation works. Tours last an hour, at most 15 people.',
  'Ride the elevator down to the launch console that never had to be used.',
  'State Historical Society of North Dakota, 555 113 1/2 Avenue NE (Highway 45), four miles north of Cooperstown; November-33 is two miles east of Cooperstown on Highway 200. Walk-ins allowed; reservations recommended for groups of 10 or more. Closed Good Friday. The page read does not give the tour price (not checked).',
  [SH('minutemanmissile','Ronald Reagan Minuteman Missile State Historic Site'),W('Oscar-Zero Missile Alert Facility')],brick='no',
  hours='Late May to Labor Day daily 9 a.m. to 5 p.m.; April and fall to Oct. 31 Tue to Sat 9 to 5; Nov to March by appointment; last tour an hour before close'),
N('whitestone-hill-battlefield','Whitestone Hill battlefield','Kulm','nd','fort','traces',46.16898,-98.85762,'area','public','walk','','1863',
  'On September 3, 1863, General Alfred Sully\'s troops attacked a camp of Yanktonai, some Dakota, Hunkpapa Lakota and Sihasapa Lakota, to punish those taken to have fought in the Dakota war of 1862. SHSND calls it the fiercest clash between Indians and soldiers in North Dakota: many Indian men, women and children were killed or taken, soldiers\' losses were comparatively light, and the camp\'s goods were destroyed on the eve of winter.',
  'Two monuments, one to the Indian dead and one to the soldiers, a marker for the settlers Tom and Mary Shimmin, a WPA fieldstone shelter beside the trail looking over part of the battlefield and a lake, and a picnic shelter (SHSND). The battlefield itself is open prairie.',
  '',
  'State Historical Society of North Dakota, 7310 86th Street SE, 23 miles southeast of Kulm in Dickey County. Free admission, donations welcome. Open year-round, no snow removal. Parking lot and pit toilets at the picnic area; the lot was not found on the map, so the pin is the site\'s street address point.',
  [SH('whitestone','Whitestone Hill State Historic Site'),W('Battle of Whitestone Hill')],brick='no',
  hours='Open year-round; no snow removal'),
N('wadeson-cabin-kathryn','Wadeson Cabin','Kathryn','nd','landmark','standing',46.67346,-97.94474,'area','public','walk','','1876 or 1878',
  'A one-and-a-half-storey cabin of hand-hewn oak with dovetailed corners on the east bank of the Sheyenne River, built by Carl Jenson (Jensen) and his nephew Jon (John) Bjerke. SHSND dates it 1876; the HMdb marker at the site says 1878. It served as a community hall, a country store, a home and at last an icehouse, and was restored in 1981.',
  'The cabin on its original fieldstone foundation, with a door and window on the east side and windows on the south and in the gable; a shadow line on the gable shows where a lean-to on the north side was taken off. Digs in 1980 and 1981 found a flagstone threshold. A marker by a small parking area on the north side tells its story. The interior is not described as open.',
  '',
  'State Historical Society of North Dakota, on the east bank of the Sheyenne River near Kathryn, Barnes County. Free (SHSND). Small parking area on the north side of the cabin (SHSND). The pin is the HMdb position of the marker beside the cabin, not checked against the cabin itself.',
  [SH('wadeson','Wadeson Cabin State Historic Site'),HM(176586,'A Tribute to Pioneer Living')],brick='no',conf='mixed'),
N('hudson-townsite-oakes','Hudson townsite','Oakes','nd','town','traces',46.09598,-98.1314,'area','public','walk','','1883–1887',
  'A paper town of the Great Dakota Boom, platted in 1883 on a railroad that was meant to run from Ellendale to Wahpeton. By 1884 it had two hotels, three stores, a newspaper, a livery, a blacksmith and a post office. In 1886 the railroads met at Oakes across the James River instead, and in the winter of 1886 to 1887 the buildings were dragged over the ice to Oakes on skids.',
  'Faint depressions, piles of stones and a few artifacts are all that remain (SHSND), with a marker dedicated in 1956. The HMdb marker, which says the colony came from New York State and named the town for the Hudson River, stands at 108th Avenue SE and 91st Street SE.',
  'A whole town put on skids and pulled across the frozen James River.',
  'State Historical Society of North Dakota, about 5 miles southwest of Oakes, Dickey County; acquired by the state in 1936. Free (SHSND). The pin is the HMdb marker at the road corner; how the townsite ground lies from it was not checked, so stay on the state ground and off the fields round it.',
  [SH('hudson','Hudson Townsite State Historic Site'),HM(112626,'Hudson')],brick='no'),
N('fort-ransom-state-historic-site','Fort Ransom site','Fort Ransom','nd','fort','traces',46.51873,-97.94046,'site','public','walk','forts','1867–1872',
  'An infantry post built from June 1867 by a battalion of the 10th Infantry to guard the overland road from Minnesota to Montana: one-storey oak log buildings in a square of 350 by 400 feet inside a twelve-foot sod and log breastwork. It was taken down in 1872 and its materials used to build Fort Seward at Jamestown, guarding the Northern Pacific crossing of the James River instead.',
  'The building sites, cellars and the dry moat with its embankment are still clear on the ground; nothing else of the fort is left. A flagpole and a marker stand by the parking area (SHSND).',
  '',
  'State Historical Society of North Dakota, southwest of the town of Fort Ransom, Ransom County. Free (SHSND). Parking area on the east side of a county road beside the marker (SHSND). The pin is in the middle of the fort square, which the LiDAR shows plainly.',
  [SH('ransom','Fort Ransom State Historic Site')],brick='no'),
N('bagg-bonanza-farm-mooreton','Bagg Bonanza Farm','Mooreton','nd','landmark','standing',46.25304,-96.86635,'site','open','walk','','1915–1935',
  'A bonanza farm started in 1915 by Frederick and Sophia Bagg, once foreman and cook on the neighbouring Downing farm. At its largest it covered about 7,000 acres of wheat, corn and clover and was run like a factory, with divided labour and cost accounting. It was split among the Baggs\' children and two key hands; it became a National Historic Landmark in 2005.',
  'Wikipedia calls it one of the best-preserved bonanza farm complexes in the country: farm buildings and houses for the family and hired men on both sides of 169th Avenue SE, plain and unornamented, with the main house adapted from a bunkhouse moved from the Downing farm. Owned by a local nonprofit and run as a museum. Interiors not checked.',
  'A wheat farm run like a factory, with the bunkhouses still standing.',
  'Owned by a local nonprofit (Wikipedia), about 1 mile south of Mooreton on 169th Avenue SE, Richland County. Its own site, baggbonanzafarm.org, would not open in this session, so its season, hours and fees were not checked.',
  [W('Frederick A. and Sophia Bagg Bonanza Farm')],brick='?',hours='?'),
N('hi-line-railroad-bridge-valley-city','Hi-Line Railroad Bridge','Valley City','nd','rail','standing',46.93889,-97.99472,'site','view','drive','','1906–1908',
  'The Northern Pacific\'s High Bridge over the Sheyenne valley, begun July 5, 1906 and in service May 8, 1908, built to spare trains the steep grades into and out of the valley. It is 3,860 feet long and 162 feet above the river; when new it was the longest bridge for its height in the world. Soldiers guarded it in both world wars, and BNSF freight trains still use it.',
  'Sixty-one spans on 30 steel towers, each standing on four concrete piers; two long spans cross the river and a third the old Soo Line tracks. About a million rivets. A working railway bridge: look from below, never on it.',
  'A mile-long steel viaduct, guarded by soldiers in two wars, still carrying freight.',
  'BNSF Railway, active line: keep off the track and the bridge. Wikipedia\'s photograph is taken from Chautauqua Park in Valley City, where the Barnes County Historical Society has an information kiosk about the bridge; the park\'s hours were not checked. The pin is Wikipedia\'s coordinate for the bridge.',
  [W('Hi-Line Railroad Bridge')],brick='no',
  th=[46.93619,-97.98906],thn='Chautauqua Park, Valley City (geocoder point)'),
N('sims-lutheran-church-almont','Sims Scandinavian Lutheran Church and parsonage','Almont','nd','worship','standing',46.7724,-101.49919,'site','open','drive','','1884–1900',
  'All that is left of Sims, a ghost town founded in 1883 that coal mining and a brickyard grew to more than 1,000 people; the 1910 census found 86. The church was built from 1896 and finished in 1900, and is said to be the oldest Lutheran church in North Dakota west of the Missouri. The 1884 parsonage, first a combined church and home, still stands beside it.',
  'The restored church, still used for worship every other Sunday (Wikipedia), and the restored parsonage, now the Sims Historical Society museum. Restoration was helped by a Save America\'s Treasures grant in 2002. A 2009 photograph on Wikimedia Commons shows a white-painted frame church with a tall spire. Interior fittings not checked.',
  'A church and parsonage alone on the prairie where a coal town of a thousand once stood.',
  'Sims church congregation and the Sims Historical Society, near Almont, Morton County. The church\'s and museum\'s own pages could not be read in this session (the Nordic American Churches page answered 403), so service times and museum hours were not checked. The pin is the geocoder\'s point for the church.',
  [W('Sims, North Dakota')],brick='no',hours='?'),
N('fargo-theatre','Fargo Theatre','Fargo','nd','civic','standing',46.87962,-96.78815,'exact','open','walk','','1926',
  'An art deco movie theatre in downtown Fargo, begun in the fall of 1925 and opened March 15, 1926, for films and vaudeville. Restored in 1999 to its historic look, it is now an art house cinema and arts centre; a second screen opened in 2009.',
  'The restored auditorium holds a four-manual, 27-rank Wurlitzer theatre organ, kept by the Red River Theatre Organ Society (Wikipedia). Films and events run on the theatre\'s calendar; going to a show is the way in.',
  '',
  'Fargo Theatre, 314 Broadway North, Fargo (OpenStreetMap address). Show times are on its calendar at fargotheatre.org; box office hours were not checked. Street parking and downtown ramps.',
  [['Fargo Theatre: About','https://fargotheatre.org/about/'],W('Fargo Theatre')],brick='?',hours='?'),
N('grassy-butte-post-office','Grassy Butte Post Office','Grassy Butte','nd','civic','standing',47.39434,-103.24818,'exact','open','drive','','1912 or 1914–1963',
  'A Ukrainian-type log building with clay plaster, built by Carl Jagol and others, which served as Grassy Butte\'s post office until 1963. McKenzie County Tourism says it was built in 1912 of logs and sod and housed the post office from 1914; Wikipedia, from the Register listing, gives 1914. The Register form calls it one of the last examples of Ukrainian log and clay construction in North Dakota.',
  'The log and plaster building itself, now a museum of the McKenzie County Historical Society; Wikipedia says it opens in summer. Interior not checked.',
  '',
  'McKenzie County Historical Society museum, 409 Main Street, Grassy Butte, off US 85. Neither page read gives its hours (not checked). Street parking.',
  [['McKenzie County Tourism: Grassy Butte Historic Post Office Museum','https://mckenzietourism.azurewebsites.net/DiscoverItem/Museums-Landmarks/Grassy-Butte-Historic-Post-Office-Museum'],W('Grassy Butte Post Office')],brick='no',conf='mixed',hours='?'),
N('maltese-cross-cabin-medora','Maltese Cross Cabin','Medora','nd','landmark','standing',46.9169,-103.5262,'site','open','walk','','1883',
  'Theodore Roosevelt\'s first cabin in Dakota Territory, used by him on the Maltese Cross ranch from 1883 to 1884, before his second ranch, the Elkhorn. Others lived in it by 1900; it was taken to the 1904 World\'s Fair, and in 1959 came to Theodore Roosevelt National Park, where it stands behind the South Unit Visitor Center.',
  'The cabin, restored to its original state, can be toured (NPS). It is not on its first site.',
  'The cabin a grieving young Roosevelt left for the Badlands ranch life that shaped him.',
  'Theodore Roosevelt National Park (National Park Service), behind the South Unit Visitor Center at the Medora entrance. NPS: the museum and the cabin are open during the visitor center\'s hours, which the page read does not give (not checked). A park entrance fee applies to the scenic drive (amount not checked). Mapped lot by the visitor center on East River Road.',
  [['NPS: Maltese Cross Cabin','https://www.nps.gov/places/maltese-cross-cabin.htm'],['NPS: South Unit','https://www.nps.gov/thro/planyourvisit/south-unit.htm'],W('Theodore Roosevelt\'s Maltese Cross Cabin')],brick='no',
  th=[46.91655,-103.52522],thn='South Unit Visitor Center lot',hours='?'),
]

